using HYWDebugAssistant.Core.Composition;
using HYWDebugAssistant.Hosting.Instances;
using HYWDebugAssistant.Sdk.Ports;
using HYWDebugAssistant.Sdk.Reporting;

namespace HYWDebugAssistant.Core.Runtime;

/// <summary>
/// **建网推导**（ADR-0037：完全重写，取代旧的"加入模块即连"）——框架派生的网络只有两类，由本文件一次性重算。
/// </summary>
/// <remarks>
/// <list type="number">
///   <item><b>命名网络</b>：端口**网络标签同名即连**（同名发送口为源、同名接收口为宿）；</item>
///   <item><b>对齐网络</b>：**未打标签**的口，两模块**接触且标记对齐**时自动连上（判定见 <see cref="DockRule"/>）。</item>
/// </list>
/// <para><b>派生 vs 显式</b>：派生网络标记 <c>IsAutoGenerated = true</c>，每次重算**先全部移除再重建**；
/// 组合件加载/用户显式建立的网络（<c>IsAutoGenerated = false</c>）**一律不动**。</para>
/// <para><b>触发时机</b>：布局提交（拖动/缩放结束）· 模块增删启停 · 端口标签变更 · 组合件加载。
/// 推导是"以现场为准重算"，**不做增量**（避免隐藏状态）。</para>
/// <para><b>与吸附的关系</b>：吸附是 UI 行为（让用户容易对上），本推导只看几何事实——吸附对齐后自然满足条件。</para>
/// </remarks>
public sealed partial class ModuleRuntime
{
    /// <summary>重算全部**派生网络**（命名 + 对齐）。</summary>
    /// <param name="notices">面向用户的提示（连通/待命名等）。</param>
    /// <param name="alignAutoNetwork">是否启用"对齐自动建网"（设置项；关 = 只做命名网络）。</param>
    private void ReconcileNetworks(List<string> notices, bool alignAutoNetwork)
    {
        var existingPairs = Content.Networks
            .Where(n => n.IsAutoGenerated)
            .Select(DescribeKey)
            .ToHashSet(StringComparer.Ordinal);

        foreach (var existing in Content.Networks.Where(n => n.IsAutoGenerated).ToList())
        {
            RemoveNetworkCore(existing.Name);
        }

        foreach (var desired in BuildNamedNetworks(notices))
        {
            AddNetworkCore(desired);
        }

        if (alignAutoNetwork)
        {
            foreach (var desired in BuildAlignmentNetworks())
            {
                AddNetworkCore(desired);
            }
        }

        // 变化提示：新出现的派生连接说清"连了什么"（用户必须看得见）
        foreach (var network in Content.Networks.Where(n => n.IsAutoGenerated))
        {
            if (existingPairs.Contains(DescribeKey(network)))
            {
                continue;
            }

            if (DescribeNetwork(network) is { Length: > 0 } description)
            {
                notices.Add($"已连接：{description}");
            }
        }
    }

    /// <summary>按**端口标签**建命名网络（同名即连）。</summary>
    private List<Network> BuildNamedNetworks(List<string> notices)
    {
        var labeled = new List<(string InstanceId, PortInstance Port, string Label)>();

        foreach (var instance in Content.Instances)
        {
            foreach (var port in instance.Ports)
            {
                var label = Content.Layout.GetPort(instance.InstanceId, port.Name).Label;
                if (!string.IsNullOrWhiteSpace(label))
                {
                    labeled.Add((instance.InstanceId, port, label.Trim()));
                }
            }
        }

        var desired = new List<Network>();

        foreach (var group in labeled.GroupBy(x => x.Label, StringComparer.Ordinal))
        {
            var label = group.Key;
            var senders = group.Where(x => x.Port.Direction == PortDirection.Send).ToList();
            var receivers = group.Where(x => x.Port.Direction == PortDirection.Receive).ToList();

            if (senders.Count == 0)
            {
                notices.Add($"网络「{label}」尚无发送端：标签已保留，等发送口填同名标签后自动连上");
                continue;
            }

            // 【ADR-0050 M1/M2】**多源 = 合法的一等组合**：同名标签的多个发送端同属**一条多源网络**
            //（旧行为"整条拒绝 + CompositionError"已作废）。宿集合 = **与任一源兼容**的接收口之并集；
            // **逐 (源,宿) 对**的兼容过滤在建立绑定时完成（`AddNetworkCore`）⇒ 不兼容者只排除那一对。
            var sources = new List<NetworkMember>();
            var targets = new List<NetworkMember>();
            var excluded = new List<string>();

            foreach (var receiver in receivers)
            {
                var compatible = false;

                foreach (var sender in senders)
                {
                    // **三层判据 + 结构回退**（与运行期/重锚同一入口）——类型标识不同默认不兼容，
                    // 派生网络**没有**"用户显式确认"这一步 ⇒ 只能按默认（拒绝）
                    if (CheckCompatibility(
                            sender.InstanceId, sender.Port,
                            receiver.InstanceId, receiver.Port).IsCompatible)
                    {
                        compatible = true;
                        break;
                    }
                }

                if (compatible)
                {
                    targets.Add(new NetworkMember(receiver.InstanceId, receiver.Port.Name, PortDirection.Receive));
                }
                else
                {
                    excluded.Add($"{receiver.InstanceId}.{receiver.Port.Name}");
                }
            }

            foreach (var sender in senders)
            {
                sources.Add(new NetworkMember(sender.InstanceId, sender.Port.Name, PortDirection.Send));
            }

            if (excluded.Count > 0)
            {
                Issues.Report($"network:{label}", new IssueReport(
                    IssueCategory.InterfaceError,
                    IssueSeverity.Warning,
                    $"网络「{label}」：成员 {string.Join("、", excluded)} **契约不兼容**（与任何源都不兼容）——**已排除该成员**（不自动转换，§5.4.1）"));
            }

            if (targets.Count == 0)
            {
                notices.Add($"网络「{label}」尚无接收端：标签已保留，等接收口填同名标签后自动连上");
                continue;
            }

            desired.Add(new Network(
                label,
                sources,
                targets,
                isAutoGenerated: true));   // 派生网络：每次重算先移除再重建
        }

        return desired;
    }

    /// <summary>按**接触且对齐**建匿名网络（仅未打标签的口）。</summary>
    private List<Network> BuildAlignmentNetworks() =>
        [.. CollectDockPairs(null)
            .GroupBy(pair => (pair.Source.InstanceId, pair.Source.PortName))
            .Select(group => new Network(
                string.Empty,   // 对齐网络匿名（= 直连）；名字只由标签产生
                new NetworkMember(group.Key.InstanceId, group.Key.PortName, PortDirection.Send),
                [.. group.Select(pair => new NetworkMember(pair.Target.InstanceId, pair.Target.PortName, PortDirection.Receive))],
                isAutoGenerated: true))];

    /// <summary>
    /// 收集当前现场的**建网候选**（发送端 → 接收端）。
    /// </summary>
    /// <param name="provisionalLayouts">
    /// 临时布局（拖动中的预览用）：给出的实例用这里的矩形，其余用工作现场里的布局。
    /// </param>
    internal List<DockPair> CollectDockPairs(IReadOnlyList<Api.ModuleLayoutView>? provisionalLayouts)
    {
        var ends = new List<DockEnd>();
        var overridden = provisionalLayouts?.ToDictionary(l => l.InstanceId, StringComparer.Ordinal) ?? [];

        foreach (var instance in Content.Instances)
        {
            Api.ModuleLayoutView? layout;
            if (overridden.TryGetValue(instance.InstanceId, out var provisional))
            {
                layout = provisional;
            }
            else
            {
                layout = Content.Layout.TryGetModule(instance.InstanceId, out var storedLayout) ? storedLayout : null;
            }

            if (layout is null || !layout.IsViewVisible)
            {
                continue;
            }

            foreach (var port in instance.Ports)
            {
                ends.Add(new DockEnd(
                    instance.InstanceId,
                    layout,
                    port.Name,
                    port.Direction == PortDirection.Send,
                    Content.Layout.GetPort(instance.InstanceId, port.Name),
                    port.Declaration.Shape,
                    port.Declaration.Semantics));
            }
        }

        return [.. DockRule.ComputeDockPairs(ends)];
    }

    /// <summary>
    /// 把网络压成"**源集合** → 宿集合"的键（用于判断重算前后是否同一条连接 / 网络身份）。
    /// </summary>
    /// <remarks>
    /// 【P40】**对外也用同一个键**：<c>RuntimeServices.GetNetworks()</c> 把它填进 `NetworkView.Key`。
    /// 【ADR-0050 M2】键含**全部源**（多源网络的身份 = 源集合 + 宿集合）。
    /// 【M5】**用"声明的源"而非"在场的源"**：身份是**声明**的属性——两条都停流的网络不得因"在场源为空"
    /// 而撞同一个键。**诊断/绑定**的键用 <see cref="DescribeSourceKey"/>（逐源，见 M7"按源归属"）。
    /// </remarks>
    internal static string DescribeKey(Network network) =>
        string.Join(",", network.DeclaredSources.Select(s => s.ToString()).OrderBy(s => s, StringComparer.Ordinal))
        + "→"
        + string.Join(",", network.Targets.Select(t => t.ToString()).OrderBy(t => t, StringComparer.Ordinal));

    /// <summary>把**单个源**与其宿集合压成键（绑定/诊断的身份：`源 → 宿集合`）。</summary>
    /// <param name="source">源成员。</param>
    /// <param name="targets">该源的宿集合。</param>
    /// <returns>身份键。</returns>
    internal static string DescribeSourceKey(NetworkMember source, IReadOnlyList<NetworkMember> targets) =>
        source + "→" + string.Join(",", targets.Select(t => t.ToString()).OrderBy(t => t, StringComparer.Ordinal));

    /// <summary>把网络描述成面向用户的短句（区别于持久化文件里的 Describe 重载）。</summary>
    private static string DescribeNetwork(Network network)
    {
        if (network.Targets.Count == 0)
        {
            return string.Empty;
        }

        var sources = network.Sources.Where(s => s.InstanceId.Length > 0).ToList();
        if (sources.Count == 0)
        {
            return string.Empty;
        }

        var name = network.IsNamed ? $"「{network.Name}」" : string.Empty;
        return $"{name}{string.Join("、", sources.Select(s => s.ToString()))} → "
            + string.Join("、", network.Targets.Select(t => $"{t.InstanceId}.{t.PortName}"));
    }
}
